/* 本美化免费发布于🍠抹茶，不准倒卖二传等一切商业化行为！，二改小猫请点餐发布于dc京昭雾 */
/* 部分代码参考源@旅程美化教程贴的老师们 */
.drawer-content {
    background-image: url('无');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}
/*气泡本体 */
.mes {
  background: none;
  background-image: url('https://i.postimg.cc/kgMLzLyV/IMG-2090.png');
  background-position: center center;
  background-repeat: repeat-y;
  background-size: contain;
  background-attachment: scroll;
  box-shadow: 0 0 0px rgba(238, 151, 169, 0.8);
}

.mes {
    --bubble-width: 100%;  
    --vertical-spacing: 2rem; 
    margin: var(--vertical-spacing) auto !important; 
}

/* ai文本 */
.mes[is_user="false"] .mes_text {
    padding: 230px 10px 120px 1px !important;
    letter-spacing: -0.5px;
}

/* 用户文本 */
.mes[is_user="true"] .mes_text {
    padding: 230px 10px 120px 1px !important; 
    letter-spacing: -0.5px;
}

.mes_text {
    line-height: 2.1; 
}
/*底层图片 */
.mes::after {
    content: "";
    position: absolute;
    bottom: 0px;/*上下位置，显示不完整调这个🍓 */
    left: 0;
    right: 0px;
    height: 160px;/*图片高度，显示不完整调这个🍓 */
    background: 
        linear-gradient(
            to top, 
            rgba(255, 255, 255, 0) 0%, 
            rgba(255, 255, 255, 0) 50%, 
            rgba(255, 255, 255, 0) 80%, 
            rgba(255, 255, 255, 0) 100%
        ),
        url('https://i.postimg.cc/GhyTr3vH/WHEE-acd69306-b0df-4a77-8a9b-57bf04c4a156-1773555842712.png') center / cover no-repeat; 
    z-index: 1;
}

/*顶层图片 */
.mes::before {
    content: "";
    position: absolute;
    top: 0px;/*上下位置，显示不完整调这个🍓 */
    left: 0;
    right: 0;
    height: 210px; /*图片高度，显示不完整调这个🍓 */
    background: 
        linear-gradient(
            to bottom, 
            rgba(255, 255, 255, 0) 0%, 
            rgba(255, 255, 255, 0) 50%, 
            rgba(255, 255, 255, 0) 80%, 
            rgba(255, 255, 255, 0) 100%
        ),
        url('https://i.postimg.cc/YjK6kv9s/WHEE-5f649cb3-8a89-4987-90f3-7abee9b0a4ab-1773557003785.png') center / cover no-repeat;
    border-radius: 0px 0px 0 0;
    z-index: 1;
}
.swipes-counter {
  position: absolute;
  top: -30px;
  right: 10px;
  z-index: 999;
  pointer-events: none;
}
.swipes-counter {
  font-size: 10px;
  opacity: 1 !important;
  color: #333 !important;
  white-space: nowrap !important;
}
/*滑块图标 */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
    appearance: none;
    width: 45px;
    height: 45px;
    background: transparent url('https://i.postimg.cc/FzvKTTSW/wu-biao-ti307-20260315082309.png') center/cover no-repeat;
    border: none;
    border-radius: 0;
    box-shadow: none;
    cursor: ew-resize;
    position: relative;
    z-index: 1;
}

input[type="range"] {
    background: #333 !important;
    box-shadow: 0 0px 0px rgba(212, 204, 133, 0.4) !important; 
    border: 1px solid #fff !important;
    padding: 2px 1px 0px 1px !important;
    height: 0px; 
}

input:not([type="file" i], [type="image" i], [type="checkbox" i], [type="radio" i]) {
  background-color: #FFFFFF;
  box-shadow: 2px 2px 0px rgba(203, 217, 224, 1);
  border-radius: 0px 0x 0px 0px;
  padding: 2px 1px;
  border: 1.5px solid #333;
  color: #333;
  outline: none;
}

/*拓展键 */
.fa-bars {
  background: url('https://i.postimg.cc/FzvKTTSW/wu-biao-ti307-20260315082309.png') center/contain no-repeat !important;
  width: 40px !important;
  height: 40px !important;
  margin-top: 2px !important;
  opacity: 1 !important
}

/*菜单键 */
#extensionsMenuButton {
  background: url('https://i.postimg.cc/FzvKTTSW/wu-biao-ti307-20260315082309.png') center/contain no-repeat !important;
  width: 40px !important;
  height: 40px !important;
  margin-top: 2px !important;
opacity: 1 !important
}

/* 发送键 */
.fa-paper-plane {
  background: url('https://i.postimg.cc/FzvKTTSW/wu-biao-ti307-20260315082309.png') center/contain no-repeat !important;
  width: 40px !important;
  height: 40px !important;
  margin-top: 2px !important;
  opacity: 1 !important
}

/* 暂停键 */
.fa-circle-stop::before {
  color: #FFFFFF;
  font-size: 1em;
  opacity: 1 !important;
}

/* 输入框 */
#send_form {
  background: url('https://i.postimg.cc/FHPYVf4c/wu-biao-ti309-20260315143022.png') center/cover no-repeat  !important;
  margin-top: 0px;
  margin-bottom: 3px;
  padding: 5px 0px !important; 
  border-radius: 0px !important;
  width: 100% !important; 
  border: 1px solid #fff !important; 
  outline: 1px solid #000 !important;
    max-width: 1000px;
    min-height: 0px !important;
    box-shadow: 0 0 0px rgba(245, 166, 184, 0.7);
}

#send_textarea {
  resize: none; 
}

/* 输入框背景色*/
textarea {
    background: 
        radial-gradient(circle at center, #FFFFFF),
        url('图片链接') !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
}

/* 输入框位置*/
#form_sheld {
  margin: 0 auto -10px auto !important; 
  transform: translateY(-20px); 
}

/* 头像位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: 45px !important; 
    left: 48% !important; 
    transform: translateX(-50%) !important;
    z-index: 9!important;
    margin: 0 !important;
}
/* 头像大小 */
.mesAvatarWrapper .avatar {
  width: 135px !important;
  height: 135px !important;
  border-radius: 0px !important;。
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  border-radius: 0% !important;
  object-fit: cover !important;
  display: block !important;
}

.mesAvatarWrapper .avatar img {
    -webkit-mask-image: url('https://i.postimg.cc/HsV4PgJZ/IMG-2094.png');
    mask-image: url('https://i.postimg.cc/HsV4PgJZ/IMG-2094.png');
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
}

/* 头像框 */
.mesAvatarWrapper::before {
  content: "";
  position: absolute;
  background-image: url('无');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  width: 110px;
  height: 110px;
  top: -16px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 3;
  pointer-events: none;
}

.mesAvatarWrapper .avatar,
.mesAvatarWrapper .avatar img,
.mesAvatarWrapper .avatar::before,
.mesAvatarWrapper .avatar::after {
  box-shadow: none !important;
  filter: none !important; 
  text-shadow: none !important; /* 移除文字阴影*/
}

q {
  background-color: #无 !important; 
  padding: px 1px !important;
  border-radius: 25px !important;
  font-style: normal !important; 
  box-shadow: 0px 0px 0px rgba(245, 166, 184, 0.5) !important;
  margin: 10px 2px !important; 
  box-decoration-break: clone !important;
  -webkit-box-decoration-break: clone !important;
}


/* 斜体 */
.mes[is_user="false"] .mes_text i,
.mes[is_user="false"] .mes_text em {
    background-color: #FFFFFF !important; 
    color: #fef8cf !important; 
    border: 1px solid #333 !important;
    padding: px px !important;
    border-radius: px !important;
    font-style: normal !important; 
}

/* 添加前缀和后缀 */
.mes[is_user="false"] .mes_text i::before,
.mes[is_user="false"] .mes_text em::before {
    content: "♡" !important;
font-size: 1em;
}

.mes[is_user="false"] .mes_text i::after,
.mes[is_user="false"] .mes_text em::after {
    content: "♡" !important;
font-size: 1em;
}

/* 时间戳 */
.timestamp {
    position: absolute !important;
    top: -20px !important;
    right: 117px !important;
    color: #949494 !important;
    font-size: 9.8px !important;
    z-index: 999 !important;
}

.timestamp::before {
    content: "" !important;
    margin-right: 0px;
  color: #949494;
  display: inline !important; /* 改为inline使其与名字在同一行 */
  vertical-align: middle;
  position: relative;
  top: -1px;
}

.mes_block {
    position: relative;
    z-index: 999 !important; 
    isolation: isolate; 
}

/* 名字位置 */
.mes_block .ch_name {
  position: relative;
  top:220px;
  left: 7px;
  max-width: calc(100% - 105px); 
  min-height: 0px;
  z-index: 5; 
  letter-spacing: 0px;
  white-space: nowrap;
  color: #949494 !important;
  font-size: 1em;
  font-weight: 100!important;
  white-space: nowrap !important;.
  z-index: 999 !important;
}

/* 添加后缀 */
.mes_block .ch_name::after {
  content: ""; /* 后缀文本 */
  margin-left: 20px;
  color: #949494;
  display: inline !important; /* 改为inline使其与名字在同一行 */
  vertical-align: middle;
  position: relative;
  top: -1px;
  left: -80px !important;
}


/* 楼层 */
.mesIDDisplay {
    position: absolute !important;
    top: 165px !important;
    left: 130px !important;
    display: flex !important;
    font-size: 0.9em!important;
    z-index: 888 !important;
    color: #646464;
    font-weight: 300 !important;
    white-space: nowrap !important;
}

.mesIDDisplay::before {
    content: "♡";
    margin-right: 0px;
    color: #949494;
    display: flex !important;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
}


/* 计时器 */
.mes .mes_timer {
    position: absolute !important;
    top: 165px !important;  
    left: 200px !important;  
    display: flex !important;
    font-size: 0.9em;
    z-index: 888 !important;
    font-weight: 300;
    color: #646464;
    white-space: nowrap !important;
}

.mes .mes_timer::before {
    content: "♡";
    margin-right: 0px;
    color: #949494;
    display: inline-block;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
}

.mes .tokenCounterDisplay {
    position: absolute !important;
    top: 165px !important;
    left: 165px !important;  
    display: flex !important;
    font-size: 0.9em;
    z-index: 888 !important;
    opacity: 1;
    color: #949494;
font-weight: 300;
}

.mes .tokenCounterDisplay::before {
    content: "♡";
    margin-right: 0px;
    color: #AEAEAE;
    display: inline-block;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
    white-space: nowrap !important;
}


/* 编辑按钮位置 */
.mes_buttons {
    position: absolute !important;
    top: -40px !important;
    right: -100px !important;
    z-index: 999 !important;
    flex-direction: row !important; 
}

/* 编辑状态时按钮位置 */
.mes_edit_buttons {
    position: relative !important;
    top: -50px !important;
    left: 20px !important;
    margin-bottom: -20px !important;
    z-index: 100 !important;
}

/* --- 编辑的省略号图标 --- */
.fa-ellipsis-h, 
.fa-ellipsis {
    background: url('https://i.postimg.cc/FzvKTTSW/wu-biao-ti307-20260315082309.png') center/contain no-repeat !important;
    width: 35px !important;   
    height: 35px !important;  
    color: transparent !important; 
z-index: 999 !important;
    opacity: 1 !important
}

/* --- 替换编辑图标 --- */
.fa-pencil-alt, 
.fa-pencil {
    background: url('https://i.postimg.cc/FzvKTTSW/wu-biao-ti307-20260315082309.png') center/contain no-repeat !important;
    width: 35px !important;
    height: 35px !important;
    color: transparent !important;
z-index: 999 !important;
    opacity: 1 !important
}


/* 导航栏 */
#top-bar::after {
    content: "";
    position: fixed;
    top: var(--topBar-height, -16px); 
    left: 0px;
    width: 100%;
    height: 45px;
    background: url('https://i.postimg.cc/4yZ4gZGh/wu-biao-ti314-20260315143338.png') center/cover no-repeat;
    z-index: 999;
}

/* 隐藏原有图标 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden; 
}

#top-bar::before {
    content: "";
    position: fixed;
    top: calc(var(--topBar-height, -15px) + 40px); 
    left: 310px;
    width: 20%;
    height: 90px; 
    background: url('https://i.postimg.cc/jqMv0m8P/WHEE-b32364b7-3cf9-4118-9f3b-5458886db65c-1773533382186.png') center/cover no-repeat;
    z-index: 999; 
}

#top-settings-holder .drawer {
    flex: 1; 

}
#top-settings-holder .drawer-icon {
    transform: scale(0.7); 
    background: linear-gradient(45deg, #333, #333) !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    color: transparent !important;
opacity: 0.9 !important
}

/* 预设 */
/* 背景 */
