}

.bogus_folder_select,
.character_select {
background-color: #FFFFFF!important;
  box-shadow: 2px 2px 0px rgba(203, 217, 224, 1);
  color: #949494 !important;
  border-radius: 1px !important;
  padding: 3px 1px !important;
  border: 0px solid rgba(255, 240, 246, 0.8) !important;
  margin: 10px 0 !important;
}
/* 隐藏收藏角色边框 */
#right-nav-panel .character_select.is_fav .avatar,
#persona-management-button .character_select.is_fav .avatar {
    outline: none !important;
    box-shadow: none !important;
}
/* 隐藏收藏角色字体颜色 */
#right-nav-panel .character_select.is_fav .ch_name,
#persona-management-button .character_select.is_fav .ch_name {
    color: inherit !important;
}

/* 用户头像设置 */
#persona-management-button .avatar img {
  width: 50px !important;  
  height: 50px !important; 
  min-width: unset !important;
  min-height: unset !important;
  top: 0px;
  left: 0px;
border: 1.5px solid #fff;
outline: 1.5px solid #000 !important;
border-radius: 1px !important;
box-shadow: 0 0px 0px rgba(213,213,213,0.9) !important;
}

/* char头像设置 */
#right-nav-panel .character_select .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    border: 1.5px solid #fff;
outline: 1.5px solid #000 !important;
    border-radius: 1px !important;
    box-shadow: 0 px px rgba(252, 235, 242,0.9) !important;
}

/*菜单面板区域*/
#options,
#extensionsMenu,
.popup .popper-modal,
#select_chat_popup {
  background-color: #141414 !important;
  box-shadow: 2px 2px 0px rgba(203, 217, 224, 1);
  color: #444444 !important;
  border-radius: 0px !important;
  padding: 1px 3px !important;
  border: 1.5px solid rgba(0, 0, 0, 1) !important;
}

/* 隐藏气泡切换键 */
#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--text-color-main);
  padding: 0;
}
.fa-chevron-right:before,
.fa-chevron-left:before {
    content: ' ' !important;
    font-size: 30px !important;
    color: var(--medium-gray) !important;
    opacity: 1;
}

/* 隐藏阴影 */
.mes_button,
.mes_edit_buttons,
#completion_prompt_manager
  #completion_prompt_manager_list
  li.completion_prompt_manager_prompt
  span
  span
  span {
  filter: none !important;
}

.text_pole:not(.objective-task) {
  background-color: var(--ui-color-sec);
  border: none;
}

.fa-bars::before,           
.fa-ellipsis-v::before,     
.fa-paper-plane::before,     
#extensionsMenuButton::before {  
  display: none !important;
  content: '' !important;  
}
body.no-blur #top-bar {
    box-shadow: none;
  }
input[type="range"] {
    filter: none; 
}
input[type="checkbox"]::before {
  content: none !important;
}
::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
}

/* 文字两端对齐*/
.mes_text {
  /* 文字两端对齐justify，左对齐改成left，居中改成center  */
  text-align: justify;
}

/* 输入框不被遮挡*/
#send_textarea {
  clip-path: none !important;
  background-color: transparent !important;
  border-color: transparent !important;
}

/* 配合正则名称全显示 */
.regex_script_name {
  white-space: normal;
}
.regex-script-label.flex-container {
  align-items: center;
}

.regex-script-container {
  width: 85%;
  /* margin-left: auto; */
}
